package com.bank.descnorm.service;

import com.bank.descnorm.trie.TrieNode;
import java.util.List;
import java.util.logging.Logger;

// Replace each word with its shortest registered root prefix.
public class DescriptorNormalizeService {
    private static final Logger log = Logger.getLogger(DescriptorNormalizeService.class.getName());

    public String replaceWithRoots(List<String> roots, String sentence) {
        TrieNode root = new TrieNode();
        for (String r : roots) {                    // build the trie of roots
            TrieNode node = root;
            for (char c : r.toCharArray())
                node = node.children.computeIfAbsent(c, k -> new TrieNode());
            node.isRoot = true;
        }
        String[] words = sentence.split(" ");
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            if (i > 0) out.append(' ');
            out.append(shorten(root, words[i]));    // shorten each word
        }
        final String r = out.toString();
        log.info(() -> "Normalised descriptor = " + r);
        return r;
    }

    private String shorten(TrieNode root, String word) {
        StringBuilder prefix = new StringBuilder();
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            if (node.isRoot) break;                 // first root found: shortest match
            TrieNode child = node.children.get(c);
            if (child == null) return word;         // no root prefixes this word
            node = child;
            prefix.append(c);
        }
        return node.isRoot ? prefix.toString() : word;
    }
}
