package com.bank.descnorm;

import com.bank.descnorm.service.DescriptorNormalizeService;
import java.util.List;
import java.util.logging.Logger;

public class DescriptorNormalizeApplication {
    private static final Logger log = Logger.getLogger(DescriptorNormalizeApplication.class.getName());

    public static void main(String[] args) {
        DescriptorNormalizeService service = new DescriptorNormalizeService();
        List<String> roots = List.of("SAL", "REN");
        String sentence = "SALARYCREDIT RENTPAID FEES";
        String normalised = service.replaceWithRoots(roots, sentence);
        log.info("Normalised descriptor sentence: " + normalised);
    }
}
